/*----- BD ----*/
CREATE DATABASE IF NOT EXISTS `inmobiliariadb_g23` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci;
USE `inmobiliariadb_g23`;

/* ######################### TABLAS #####################################*/
CREATE TABLE IF NOT EXISTS `propietario` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `dni` VARCHAR(20) NOT NULL UNIQUE,
  `nombre` VARCHAR(50) NOT NULL,
  `apellido` VARCHAR(50) NOT NULL,
  `telefono` VARCHAR(30) NOT NULL,
  `email` VARCHAR(100) NOT NULL
) ENGINE=InnoDB;

    /*    Inquilino    */
CREATE TABLE IF NOT EXISTS `inquilino` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `dni` VARCHAR(20) NOT NULL UNIQUE,
  `nombre` VARCHAR(50) NOT NULL,
  `apellido` VARCHAR(50) NOT NULL,
  `telefono` VARCHAR(30) NOT NULL,
  `email` VARCHAR(100) NOT NULL
) ENGINE=InnoDB;

    /*   Tipo Inmueble    */
CREATE TABLE IF NOT EXISTS `tipo_inmueble` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `nombre` VARCHAR(100) NOT NULL UNIQUE
) ENGINE=InnoDB;

    /*    Usuario    */
CREATE TABLE IF NOT EXISTS `usuario` (
  `idUsuario` INT AUTO_INCREMENT PRIMARY KEY,
  `nombre` VARCHAR(50) NOT NULL,
  `apellido` VARCHAR(50) NOT NULL,
  `email` VARCHAR(100) NOT NULL UNIQUE,
  `clave` VARCHAR(255) NOT NULL,
  `avatarUrl` VARCHAR(500) NULL,
  `rol` ENUM('Administrador', 'Empleado') NOT NULL DEFAULT 'Empleado',
  `estado` BOOLEAN NOT NULL DEFAULT TRUE
) ENGINE=InnoDB;


    /*    Inmueble    */
CREATE TABLE IF NOT EXISTS `inmueble` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_propietario` INT NOT NULL,
    `id_tipo_inmueble` INT NOT NULL,
    `direccion` VARCHAR(200) NOT NULL,
    `cupo` INT NOT NULL,
    `latitud` DECIMAL(10,7) NOT NULL,
    `longitud` DECIMAL(10,7) NOT NULL,
    `precio_por_dia` DECIMAL(12,2) NOT NULL,
    `porcentaje_reserva` DECIMAL(5,2) NOT NULL,
    `disponible` BOOLEAN NOT NULL DEFAULT TRUE,
    `estado` BOOLEAN NOT NULL DEFAULT TRUE,
    INDEX ix_inmueble_estado_propietario (estado, id_propietario, id),

    CONSTRAINT `fk_inmueble_propietario`
        FOREIGN KEY (`id_propietario`)
        REFERENCES `propietario` (`id`),

    CONSTRAINT `fk_inmueble_tipo`
        FOREIGN KEY (`id_tipo_inmueble`)
        REFERENCES `tipo_inmueble` (`id`),

    CONSTRAINT `chk_inmueble_cupo`
        CHECK (`cupo` > 0),

    CONSTRAINT `chk_inmueble_precio`
        CHECK (`precio_por_dia` > 0),

    CONSTRAINT `chk_inmueble_porcentaje`
        CHECK (`porcentaje_reserva` >= 0
              AND `porcentaje_reserva` <= 100)
) ENGINE=InnoDB;

/* ---- Compatibilidad de inmuebles con bases existentes ---- */
SET @actualizar_inmueble = IF(
    EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'inmueble' AND column_name = 'estado'),
    'SELECT 1', 'ALTER TABLE inmueble ADD COLUMN estado BOOLEAN NOT NULL DEFAULT TRUE');
PREPARE actualizar_inmueble FROM @actualizar_inmueble;
EXECUTE actualizar_inmueble;
DEALLOCATE PREPARE actualizar_inmueble;
SET @actualizar_inmueble = IF(
    EXISTS (SELECT 1 FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'inmueble' AND index_name = 'ix_inmueble_estado_propietario'),
    'SELECT 1', 'CREATE INDEX ix_inmueble_estado_propietario ON inmueble (estado, id_propietario, id)');
PREPARE actualizar_inmueble FROM @actualizar_inmueble;
EXECUTE actualizar_inmueble;
DEALLOCATE PREPARE actualizar_inmueble;
/* ---- Fin compatibilidad de inmuebles ---- */

CREATE TABLE IF NOT EXISTS inmueble_imagen (
    id INT AUTO_INCREMENT PRIMARY KEY,
    id_inmueble INT NOT NULL,
    contenido_base64 MEDIUMTEXT CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    es_portada BOOLEAN NOT NULL DEFAULT FALSE,
    estado BOOLEAN NOT NULL DEFAULT TRUE,
    portada_activa INT GENERATED ALWAYS AS
        (CASE WHEN estado = 1 AND es_portada = 1 THEN id_inmueble ELSE NULL END) STORED,
    CONSTRAINT fk_imagen_inmueble FOREIGN KEY (id_inmueble) REFERENCES inmueble(id),
    UNIQUE KEY ux_imagen_portada (portada_activa),
    INDEX ix_imagen_inmueble_estado (id_inmueble, estado, id)
) ENGINE=InnoDB;

        /*    Reserva    */
CREATE TABLE IF NOT EXISTS `reserva` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_inquilino` INT NOT NULL,
    `id_inmueble` INT NOT NULL,
    `fecha_desde` DATE NOT NULL,
    `fecha_hasta` DATE NOT NULL,
    `monto_por_dia` DECIMAL(12,2) NOT NULL,
    `anulada` BOOLEAN NOT NULL DEFAULT FALSE,
    `id_usuario_creador` INT NULL,
    `fecha_creacion` DATETIME NULL,
    `id_usuario_anulador` INT NULL,
    `fecha_anulacion` DATETIME NULL,
    `fecha_terminacion` DATE NULL,
    `id_usuario_terminador` INT NULL,

    CONSTRAINT `fk_reserva_inquilino`
        FOREIGN KEY (`id_inquilino`)
        REFERENCES `inquilino` (`id`),

    CONSTRAINT `fk_reserva_inmueble`
        FOREIGN KEY (`id_inmueble`)
        REFERENCES `inmueble` (`id`),

    CONSTRAINT `fk_reserva_usuario_creador`
      FOREIGN KEY (`id_usuario_creador`)
      REFERENCES `usuario` (`idUsuario`),

    CONSTRAINT `fk_reserva_usuario_anulador`
      FOREIGN KEY (`id_usuario_anulador`)
      REFERENCES `usuario` (`idUsuario`),

    CONSTRAINT `chk_reserva_fechas`
        CHECK (`fecha_hasta` >= `fecha_desde`),

    CONSTRAINT `chk_reserva_monto`
        CHECK (`monto_por_dia` > 0),

    CONSTRAINT `fk_reserva_usuario_terminador`
      FOREIGN KEY (`id_usuario_terminador`)
      REFERENCES `usuario` (`idUsuario`)
) ENGINE=InnoDB;

    /*    Pago    */
CREATE TABLE IF NOT EXISTS `pago` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_reserva` INT NOT NULL,
    `concepto` VARCHAR(200) NOT NULL,
    `fecha_pago` DATE NOT NULL,
    `importe` DECIMAL(12,2) NOT NULL,
    `anulada` BOOLEAN NOT NULL DEFAULT FALSE,

    `id_usuario_creador` INT NULL,
    `fecha_creacion` DATETIME NULL,

    `id_usuario_anulador` INT NULL,
    `fecha_anulacion` DATETIME NULL,

    CONSTRAINT `fk_pago_reserva`
        FOREIGN KEY (`id_reserva`)
        REFERENCES `reserva` (`id`),

    CONSTRAINT `fk_pago_usuario_creador`
        FOREIGN KEY (`id_usuario_creador`)
        REFERENCES `usuario` (`idUsuario`),

    CONSTRAINT `fk_pago_usuario_anulador`
        FOREIGN KEY (`id_usuario_anulador`)
        REFERENCES `usuario` (`idUsuario`),

    CONSTRAINT `chk_pago_importe`
        CHECK (`importe` > 0)
) ENGINE=InnoDB;


