/* ---- Imágenes de ejemplo: 12 portadas y galería de Monoambiente 2 ---- */
-- WebP calidad 80, máximo 1600 px; base64 sin prefijo.
START TRANSACTION;
-- casa.png -> Casa, Av. España 1250
SET @imagen_ejemplo_base64 = '';
INSERT INTO inmueble_imagen (id_inmueble, contenido_base64, es_portada, estado)
SELECT i.id, @imagen_ejemplo_base64,
    NOT EXISTS (SELECT 1 FROM inmueble_imagen portada WHERE portada.id_inmueble = i.id AND portada.estado = TRUE AND portada.es_portada = TRUE),
    TRUE
FROM inmueble i
INNER JOIN tipo_inmueble t ON t.id = i.id_tipo_inmueble
INNER JOIN propietario p ON p.id = i.id_propietario
WHERE t.nombre = 'Casa' AND i.direccion = 'Av. España 1250' AND p.dni = '11111111' AND i.estado = TRUE
  AND NOT EXISTS (SELECT 1 FROM inmueble_imagen im WHERE im.id_inmueble = i.id AND im.contenido_base64 = @imagen_ejemplo_base64);

